import React, { useState, useEffect } from 'react';
import { findRelevantJobs, analyzeJobFit } from '../services/geminiService';
import { JobSearchResult, UserProfile } from '../types';
import { 
  Bot, 
  Play, 
  Loader2, 
  CheckCircle2, 
  Send, 
  Activity,
  Mail,
  ExternalLink,
  Ban,
  Settings2,
  Calendar,
  Globe,
  MapPin
} from 'lucide-react';

interface AutoPilotProps {
  userProfile: UserProfile;
}

export const AutoPilot: React.FC<AutoPilotProps> = ({ userProfile }) => {
  const [isActive, setIsActive] = useState(true);
  const [isRunning, setIsRunning] = useState(false);
  const [jobs, setJobs] = useState<JobSearchResult[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [emailNotification, setEmailNotification] = useState<string | null>(null);

  // Configuration State
  const [config, setConfig] = useState({
    frequency: 'daily_9',
    location: userProfile.logistics.location || userProfile.location,
    minScore: 90,
    dateRange: '24h',
    customDate: ''
  });

  // Sync config location if profile updates
  useEffect(() => {
    setConfig(prev => ({
      ...prev,
      location: userProfile.logistics.location || userProfile.location
    }));
  }, [userProfile.logistics.location, userProfile.location]);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev]);

  const getDateCriteriaString = () => {
    switch (config.dateRange) {
      case '24h': return 'in the last 24 hours';
      case '3d': return 'in the last 3 days';
      case '7d': return 'in the last 7 days';
      case 'custom': return config.customDate ? `after ${config.customDate}` : 'recently';
      default: return 'recently';
    }
  };

  const runAutomation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setJobs([]);
    setLogs([]);
    setEmailNotification(null);

    try {
      const dateStr = getDateCriteriaString();
      addLog("Starting automated scan agent...");
      addLog(`Settings: ${config.location} | Threshold: ${config.minScore}% | Date: ${dateStr}`);

      addLog("Querying Google Search for active global listings...");

      const searchProfile = {
        ...userProfile,
        logistics: {
            ...userProfile.logistics,
            location: config.location
        },
        location: config.location
      };

      const foundJobs = await findRelevantJobs(searchProfile, dateStr);
      setJobs(foundJobs);
      addLog(`Found ${foundJobs.length} potential matches. Analyzing fit...`);

      for (const job of foundJobs) {
        setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'analyzing' } : j));
        addLog(`Analyzing: ${job.title} at ${job.company}...`);

        try {
          const analysis = await analyzeJobFit(job.description, userProfile);
          const isMatch = analysis.matchScore >= config.minScore;

          setJobs(current => current.map(j => {
            if (j.id === job.id) {
              return { 
                ...j, 
                analysis, 
                status: isMatch ? 'matched' : 'rejected' 
              };
            }
            return j;
          }));

          if (isMatch) {
            addLog(`✅ MATCH FOUND (${analysis.matchScore}%): ${job.company}. Applying...`);
            await new Promise(r => setTimeout(r, 1500));

            setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'applied' } : j));
            addLog(`🚀 Application Submitted to ${job.company}`);

            const notifText = `Applied to ${job.title} at ${job.company} (Score: ${analysis.matchScore}%)`;
            setEmailNotification(notifText);
            addLog(`📧 Notification sent to ${userProfile.email}`);
          } else {
            addLog(`❌ Skipped (${analysis.matchScore}%). Below ${config.minScore}% threshold.`);
          }
        } catch (e) {
          addLog(`⚠️ Error analyzing ${job.company}`);
          setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'rejected' } : j));
        }

        await new Promise(r => setTimeout(r, 800));
      }

      addLog("Scan cycle complete. Agent sleeping.");
    } catch (error) {
      addLog("Error during automation run.");
      console.error(error);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-100px)]">
      {/* Control Panel */}
      <div className="lg:col-span-1 space-y-6 flex flex-col h-full">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-purple-600 p-2 rounded-lg">
              <Bot className="text-white h-6 w-6" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-900">Auto-Pilot Agent</h2>
              <p className="text-xs text-slate-500">Global Executive Job Bot</p>
            </div>
          </div>

          <div className="flex items-center justify-between bg-slate-50 p-4 rounded-lg border border-slate-100 mb-6">
            <div>
              <p className="text-sm font-semibold text-slate-900">Daily Automation</p>
              <p className="text-xs text-slate-500">{isActive ? 'Active' : 'Paused'}</p>
            </div>
            <button 
              onClick={() => setIsActive(!isActive)}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${isActive ? 'bg-green-500' : 'bg-slate-300'}`}
            >
              <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${isActive ? 'translate-x-6' : 'translate-x-1'}`} />
            </button>
          </div>

          <div className="space-y-4">
             <div className="bg-blue-50 p-4 rounded-md border border-blue-100 space-y-4">
               <div className="flex items-center justify-between border-b border-blue-200 pb-2 mb-2">
                 <h4 className="text-xs font-bold text-blue-800 uppercase">Automation Rules</h4>
                 <Settings2 size={14} className="text-blue-600" />
               </div>

               {/* Frequency Setting */}
               <div className="space-y-1">
                 <label className="text-xs font-medium text-blue-900 block">Scan Frequency</label>
                 <select 
                    value={config.frequency}
                    onChange={(e) => setConfig({...config, frequency: e.target.value})}
                    className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                 >
                    <option value="daily_9">Daily at 09:00 (Local Time)</option>
                    <option value="daily_12">Daily at 12:00 (Local Time)</option>
                    <option value="every_6">Every 6 Hours</option>
                    <option value="manual">Manual Trigger Only</option>
                 </select>
               </div>

               {/* Location Selection - World Coverage */}
               <div className="space-y-2">
                  <label className="text-xs font-medium text-blue-900 flex items-center gap-1">
                    <Globe size={12} className="text-blue-600" /> Global Target Region
                  </label>

                  <div className="space-y-2">
                    {/* Broad Region Presets */}
                    <select
                        value={config.location}
                        onChange={(e) => setConfig({...config, location: e.target.value})}
                        className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                    >
                        <option value={userProfile.logistics.location || userProfile.location}>📍 Profile: {userProfile.logistics.location || userProfile.location}</option>
                        <option value="South Africa">South Africa (National)</option>
                        <option value="United States">United States (National)</option>
                        <option value="United Kingdom">United Kingdom (National)</option>
                        <option value="European Union">European Union (National)</option>
                        <option value="United Arab Emirates">United Arab Emirates</option>
                        <option value="Singapore">Singapore</option>
                        <option value="Australia">Australia</option>
                        <option value="Remote">Remote (Global)</option>
                        <option value="">Custom... (Type below)</option>
                    </select>

                    {/* Specific Location Search Input */}
                    <div className="relative group">
                      <div className="absolute left-2.5 top-2.5 text-blue-400">
                        <MapPin size={12} />
                      </div>
                      <input 
                        type="text"
                        placeholder="Country, State, City, or Town..."
                        value={config.location}
                        onChange={(e) => setConfig({...config, location: e.target.value})}
                        className="w-full text-xs p-2 pl-8 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                      />
                    </div>
                    <p className="text-[10px] text-slate-500 italic">Enter any location worldwide (e.g., "Manhattan, New York", "Berlin, Germany").</p>
                  </div>
               </div>

                {/* Date Range Setting */}
               <div className="space-y-1">
                  <label className="text-xs font-medium text-blue-900 flex items-center gap-1">
                    <Calendar size={10} /> Date Posted
                  </label>
                  <select
                      value={config.dateRange}
                      onChange={(e) => setConfig({...config, dateRange: e.target.value})}
                      className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                  >
                      <option value="24h">Last 24 Hours</option>
                      <option value="3d">Last 3 Days</option>
                      <option value="7d">Last 7 Days</option>
                      <option value="custom">Custom Date (Since...)</option>
                  </select>

                  {config.dateRange === 'custom' && (
                    <input 
                      type="date"
                      value={config.customDate}
                      onChange={(e) => setConfig({...config, customDate: e.target.value})}
                      className="w-full text-xs p-2 mt-1 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                    />
                  )}
               </div>

               {/* Threshold Setting */}
               <div className="space-y-1">
                  <label className="text-xs font-medium text-blue-900 block">Minimum Match Score</label>
                  <select
                      value={config.minScore}
                      onChange={(e) => setConfig({...config, minScore: Number(e.target.value)})}
                      className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                  >
                      <option value={95}>95% (Strict - Top Matches Only)</option>
                      <option value={90}>90% (Recommended - High Fit)</option>
                      <option value={85}>85% (Balanced)</option>
                      <option value={80}>80% (Broad Search)</option>
                  </select>
               </div>
             </div>

             <button 
              onClick={runAutomation}
              disabled={isRunning}
              className={`w-full py-3 px-4 rounded-lg font-semibold flex items-center justify-center gap-2 transition-all ${
                isRunning 
                  ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                  : 'bg-slate-900 text-white hover:bg-slate-800 shadow-lg'
              }`}
             >
               {isRunning ? <Loader2 className="animate-spin h-4 w-4" /> : <Play className="h-4 w-4" />}
               {isRunning ? 'Agent Running...' : 'Run Global Scan'}
             </button>
          </div>
        </div>

        {/* Live Logs */}
        <div className="bg-slate-900 rounded-xl shadow-sm border border-slate-800 p-4 flex-1 flex flex-col min-h-0">
          <div className="flex items-center gap-2 text-slate-400 mb-3 pb-3 border-b border-slate-800">
            <Activity size={14} />
            <span className="text-xs font-mono font-bold uppercase">System Logs</span>
          </div>
          <div className="flex-1 overflow-y-auto font-mono text-xs space-y-2 pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
            {logs.length === 0 && <span className="text-slate-600 italic">Waiting to start...</span>}
            {logs.map((log, i) => (
              <div key={i} className="text-green-400 border-l-2 border-slate-700 pl-2 py-0.5">
                <span className="text-slate-500 mr-2">[{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}]</span>
                {log}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="lg:col-span-2 flex flex-col h-full overflow-hidden">
        <div className="flex items-center justify-between mb-4 flex-shrink-0">
          <h3 className="text-lg font-bold text-slate-900">Opportunities in {config.location || 'Selected Region'}</h3>
          {emailNotification && (
             <div className="flex items-center gap-2 bg-green-100 text-green-800 px-3 py-1 rounded-full text-xs font-bold animate-pulse">
               <Mail size={12} />
               Email Sent to User
             </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 space-y-4 scrollbar-hide">
          {jobs.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
              <Bot size={48} className="mb-4 opacity-50" />
              <p className="text-lg font-medium">Agent is sleeping</p>
              <p className="text-sm text-center max-w-md mt-2">
                Configure your global rules and click "Run Global Scan" to find jobs matching your leadership profile (Threshold: {config.minScore}%).
              </p>
            </div>
          ) : (
            jobs.map((job) => (
              <div key={job.id} className={`bg-white rounded-xl shadow-sm border p-5 transition-all ${
                job.status === 'applied' ? 'border-green-200 bg-green-50/30' : 
                job.status === 'rejected' ? 'border-slate-100 opacity-60' : 
                'border-slate-200'
              }`}>
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <h4 className="font-bold text-slate-900 text-lg">{job.title}</h4>
                    <div className="flex items-center gap-2 text-sm text-slate-600">
                      <span>{job.company}</span>
                      <span>•</span>
                      <span>{job.location}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                     {job.status === 'pending' && <span className="bg-slate-100 text-slate-500 text-xs font-bold px-2 py-1 rounded">Pending</span>}
                     {job.status === 'analyzing' && <span className="bg-blue-100 text-blue-600 text-xs font-bold px-2 py-1 rounded flex items-center gap-1"><Loader2 size={10} className="animate-spin"/> Analyzing</span>}
                     {job.status === 'matched' && <span className="bg-green-100 text-green-700 text-xs font-bold px-2 py-1 rounded">Matched</span>}
                     {job.status === 'rejected' && <span className="bg-slate-100 text-slate-400 text-xs font-bold px-2 py-1 rounded">Skipped</span>}
                     {job.status === 'applied' && <span className="bg-green-600 text-white text-xs font-bold px-2 py-1 rounded flex items-center gap-1"><Send size={10}/> Applied</span>}
                  </div>
                </div>

                {job.analysis && (
                  <div className="mt-4 pt-4 border-t border-slate-100 grid md:grid-cols-5 gap-4">
                    <div className="md:col-span-1">
                      <div className="text-xs font-bold text-slate-400 uppercase mb-1">Match Score</div>
                      <div className={`text-2xl font-bold ${job.analysis.matchScore >= config.minScore ? 'text-green-600' : 'text-slate-400'}`}>
                        {job.analysis.matchScore}%
                      </div>
                    </div>
                    <div className="md:col-span-4">
                       <div className="text-xs font-bold text-slate-400 uppercase mb-1">AI Analysis</div>
                       <p className="text-sm text-slate-700">{job.analysis.summary}</p>
                       {job.status === 'rejected' && (
                         <div className="flex items-center gap-1 text-xs text-red-500 mt-2 font-medium">
                            <Ban size={12} /> Match score below {config.minScore}% threshold.
                         </div>
                       )}
                    </div>
                  </div>
                )}

                <div className="mt-4 flex justify-end">
                   <a href={job.url} target="_blank" rel="noreferrer" className="text-xs text-blue-600 hover:underline flex items-center gap-1">
                      View Original Post <ExternalLink size={10} />
                   </a>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { findRelevantJobs, analyzeJobFit } from '../services/geminiService';
import { JobSearchResult, UserProfile } from '../types';
import { 
  Bot, 
  Play, 
  Loader2, 
  Send, 
  Activity,
  Mail,
  ExternalLink,
  Ban,
  Settings2,
  Calendar,
  Globe,
  MapPin,
  ChevronRight
} from 'lucide-react';

// Sample hierarchical data for demonstration
const LOCATION_DATA: any = {
  "South Africa": {
    "Gauteng": {
      "Johannesburg": ["Sandton", "Randburg", "Midrand", "Soweto"],
      "Pretoria": ["Centurion", "Hatfield", "Silverton", "Brooklyn"],
    },
    "Western Cape": {
      "Cape Town": ["City Bowl", "Bellville", "Somerset West", "Stellenbosch"],
      "George": ["Wilderness", "Victoria Bay"]
    },
    "KwaZulu-Natal": {
      "Durban": ["Umhlanga", "Berea", "Westville"],
      "Pietermaritzburg": ["Hilton", "Howick"]
    }
  },
  "United States": {
    "New York": {
      "New York City": ["Manhattan", "Brooklyn", "Queens", "Bronx"],
      "Buffalo": ["Amherst", "Cheektowaga"]
    },
    "California": {
      "Los Angeles": ["Santa Monica", "Beverly Hills", "Hollywood"],
      "San Francisco": ["SoMa", "Mission District", "Marina"]
    },
    "Texas": {
      "Houston": ["The Woodlands", "Sugar Land"],
      "Austin": ["Round Rock", "Cedar Park"]
    }
  },
  "United Kingdom": {
    "England": {
      "London": ["City of London", "Westminster", "Camden", "Greenwich"],
      "Manchester": ["Salford", "Trafford"]
    },
    "Scotland": {
      "Edinburgh": ["Leith", "Old Town"],
      "Glasgow": ["West End", "City Centre"]
    }
  }
};

interface AutoPilotProps {
  userProfile: UserProfile;
}

export const AutoPilot: React.FC<AutoPilotProps> = ({ userProfile }) => {
  const [isActive, setIsActive] = useState(true);
  const [isRunning, setIsRunning] = useState(false);
  const [jobs, setJobs] = useState<JobSearchResult[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [emailNotification, setEmailNotification] = useState<string | null>(null);

  // Hierarchical Location State
  const [locSelection, setLocSelection] = useState({
    country: "South Africa",
    state: "Gauteng",
    city: "Pretoria",
    town: "Centurion",
    customCountry: "",
    customState: "",
    customCity: "",
    customTown: ""
  });

  // Derived selections
  const countries = useMemo(() => [...Object.keys(LOCATION_DATA), "Other..."], []);
  const states = useMemo(() => {
    const data = LOCATION_DATA[locSelection.country];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [locSelection.country]);

  const cities = useMemo(() => {
    const data = LOCATION_DATA[locSelection.country]?.[locSelection.state];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [locSelection.country, locSelection.state]);

  const towns = useMemo(() => {
    const data = LOCATION_DATA[locSelection.country]?.[locSelection.state]?.[locSelection.city];
    return data ? [...data, "Other..."] : ["Other..."];
  }, [locSelection.country, locSelection.state, locSelection.city]);

  // Configuration State
  const [config, setConfig] = useState({
    frequency: 'daily_9',
    minScore: 90,
    dateRange: '24h',
    customDate: ''
  });

  // Calculate full location string
  const fullLocation = useMemo(() => {
    const c = locSelection.country === "Other..." ? locSelection.customCountry : locSelection.country;
    const s = locSelection.state === "Other..." ? locSelection.customState : locSelection.state;
    const ci = locSelection.city === "Other..." ? locSelection.customCity : locSelection.city;
    const t = locSelection.town === "Other..." ? locSelection.customTown : locSelection.town;

    return [t, ci, s, c].filter(Boolean).join(", ");
  }, [locSelection]);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev]);

  const getDateCriteriaString = () => {
    switch (config.dateRange) {
      case '24h': return 'in the last 24 hours';
      case '3d': return 'in the last 3 days';
      case '7d': return 'in the last 7 days';
      case 'custom': return config.customDate ? `after ${config.customDate}` : 'recently';
      default: return 'recently';
    }
  };

  const runAutomation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setJobs([]);
    setLogs([]);
    setEmailNotification(null);

    try {
      const dateStr = getDateCriteriaString();
      addLog("Starting automated scan agent...");
      addLog(`Target: ${fullLocation}`);
      addLog(`Settings: Threshold ${config.minScore}% | Date: ${dateStr}`);

      addLog("Querying Google Search for active global listings...");

      const searchProfile = {
        ...userProfile,
        logistics: {
            ...userProfile.logistics,
            location: fullLocation
        },
        location: fullLocation
      };

      const foundJobs = await findRelevantJobs(searchProfile, dateStr);
      setJobs(foundJobs);
      addLog(`Found ${foundJobs.length} potential matches. Analyzing fit...`);

      for (const job of foundJobs) {
        setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'analyzing' } : j));
        addLog(`Analyzing: ${job.title} at ${job.company}...`);

        try {
          const analysis = await analyzeJobFit(job.description, userProfile);
          const isMatch = analysis.matchScore >= config.minScore;

          setJobs(current => current.map(j => {
            if (j.id === job.id) {
              return { 
                ...j, 
                analysis, 
                status: isMatch ? 'matched' : 'rejected' 
              };
            }
            return j;
          }));

          if (isMatch) {
            addLog(`✅ MATCH FOUND (${analysis.matchScore}%): ${job.company}. Applying...`);
            await new Promise(r => setTimeout(r, 1500));

            setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'applied' } : j));
            addLog(`🚀 Application Submitted to ${job.company}`);

            const notifText = `Applied to ${job.title} at ${job.company} (Score: ${analysis.matchScore}%)`;
            setEmailNotification(notifText);
            addLog(`📧 Notification sent to ${userProfile.email}`);
          } else {
            addLog(`❌ Skipped (${analysis.matchScore}%). Below ${config.minScore}% threshold.`);
          }
        } catch (e) {
          addLog(`⚠️ Error analyzing ${job.company}`);
          setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'rejected' } : j));
        }

        await new Promise(r => setTimeout(r, 800));
      }

      addLog("Scan cycle complete. Agent sleeping.");
    } catch (error) {
      addLog("Error during automation run.");
      console.error(error);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-100px)]">
      {/* Control Panel */}
      <div className="lg:col-span-1 space-y-6 flex flex-col h-full">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 overflow-y-auto scrollbar-hide">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-purple-600 p-2 rounded-lg">
              <Bot className="text-white h-6 w-6" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-900">Auto-Pilot Agent</h2>
              <p className="text-xs text-slate-500">Global Executive Job Bot</p>
            </div>
          </div>

          <div className="flex items-center justify-between bg-slate-50 p-4 rounded-lg border border-slate-100 mb-6">
            <div>
              <p className="text-sm font-semibold text-slate-900">Daily Automation</p>
              <p className="text-xs text-slate-500">{isActive ? 'Active' : 'Paused'}</p>
            </div>
            <button 
              onClick={() => setIsActive(!isActive)}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${isActive ? 'bg-green-500' : 'bg-slate-300'}`}
            >
              <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${isActive ? 'translate-x-6' : 'translate-x-1'}`} />
            </button>
          </div>

          <div className="space-y-4">
             <div className="bg-blue-50 p-4 rounded-md border border-blue-100 space-y-4">
               <div className="flex items-center justify-between border-b border-blue-200 pb-2 mb-2">
                 <h4 className="text-xs font-bold text-blue-800 uppercase">Automation Rules</h4>
                 <Settings2 size={14} className="text-blue-600" />
               </div>

               {/* Frequency Setting */}
               <div className="space-y-1">
                 <label className="text-xs font-medium text-blue-900 block">Scan Frequency</label>
                 <select 
                    value={config.frequency}
                    onChange={(e) => setConfig({...config, frequency: e.target.value})}
                    className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                 >
                    <option value="daily_9">Daily at 09:00 (Local Time)</option>
                    <option value="daily_12">Daily at 12:00 (Local Time)</option>
                    <option value="every_6">Every 6 Hours</option>
                    <option value="manual">Manual Trigger Only</option>
                 </select>
               </div>

               {/* Hierarchical Location Selection */}
               <div className="space-y-3 pt-2 border-t border-blue-100">
                  <label className="text-xs font-bold text-blue-900 flex items-center gap-1 uppercase tracking-tight">
                    <Globe size={12} className="text-blue-600" /> Target Region
                  </label>

                  {/* Country */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Country</label>
                    <select
                        value={locSelection.country}
                        onChange={(e) => setLocSelection({...locSelection, country: e.target.value, state: "Other...", city: "Other...", town: "Other..."})}
                        className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700"
                    >
                        {countries.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    {locSelection.country === "Other..." && (
                      <input 
                        type="text"
                        placeholder="Type country name..."
                        value={locSelection.customCountry}
                        onChange={(e) => setLocSelection({...locSelection, customCountry: e.target.value})}
                        className="w-full text-xs p-2 mt-1 rounded border border-blue-300 bg-white"
                      />
                    )}
                  </div>

                  {/* State / Province */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">State / Province</label>
                    <select
                        value={locSelection.state}
                        onChange={(e) => setLocSelection({...locSelection, state: e.target.value, city: "Other...", town: "Other..."})}
                        className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700"
                    >
                        {states.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                    {locSelection.state === "Other..." && (
                      <input 
                        type="text"
                        placeholder="Type state/region name..."
                        value={locSelection.customState}
                        onChange={(e) => setLocSelection({...locSelection, customState: e.target.value})}
                        className="w-full text-xs p-2 mt-1 rounded border border-blue-300 bg-white"
                      />
                    )}
                  </div>

                  {/* City */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">City</label>
                    <select
                        value={locSelection.city}
                        onChange={(e) => setLocSelection({...locSelection, city: e.target.value, town: "Other..."})}
                        className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700"
                    >
                        {cities.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    {locSelection.city === "Other..." && (
                      <input 
                        type="text"
                        placeholder="Type city name..."
                        value={locSelection.customCity}
                        onChange={(e) => setLocSelection({...locSelection, customCity: e.target.value})}
                        className="w-full text-xs p-2 mt-1 rounded border border-blue-300 bg-white"
                      />
                    )}
                  </div>

                  {/* Town */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Town / Suburb</label>
                    <select
                        value={locSelection.town}
                        onChange={(e) => setLocSelection({...locSelection, town: e.target.value})}
                        className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700"
                    >
                        {towns.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                    {locSelection.town === "Other..." && (
                      <input 
                        type="text"
                        placeholder="Type town/suburb name..."
                        value={locSelection.customTown}
                        onChange={(e) => setLocSelection({...locSelection, customTown: e.target.value})}
                        className="w-full text-xs p-2 mt-1 rounded border border-blue-300 bg-white"
                      />
                    )}
                  </div>

                  <div className="bg-blue-100/50 p-2 rounded flex items-start gap-2 border border-blue-200">
                    <MapPin size={14} className="text-blue-600 mt-0.5" />
                    <p className="text-[10px] text-blue-800 leading-tight">
                      <strong>Current Target:</strong><br/>
                      {fullLocation || "Global"}
                    </p>
                  </div>
               </div>

                {/* Date Range Setting */}
               <div className="space-y-1">
                  <label className="text-xs font-medium text-blue-900 flex items-center gap-1">
                    <Calendar size={10} /> Date Posted
                  </label>
                  <select
                      value={config.dateRange}
                      onChange={(e) => setConfig({...config, dateRange: e.target.value})}
                      className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                  >
                      <option value="24h">Last 24 Hours</option>
                      <option value="3d">Last 3 Days</option>
                      <option value="7d">Last 7 Days</option>
                      <option value="custom">Custom Date (Since...)</option>
                  </select>
               </div>

               {/* Threshold Setting */}
               <div className="space-y-1">
                  <label className="text-xs font-medium text-blue-900 block">Minimum Match Score</label>
                  <select
                      value={config.minScore}
                      onChange={(e) => setConfig({...config, minScore: Number(e.target.value)})}
                      className="w-full text-xs p-2 rounded border border-blue-200 bg-white text-slate-700 focus:outline-none focus:border-blue-500 shadow-sm"
                  >
                      <option value={95}>95% (Strict)</option>
                      <option value={90}>90% (Recommended)</option>
                      <option value={85}>85% (Balanced)</option>
                  </select>
               </div>
             </div>

             <button 
              onClick={runAutomation}
              disabled={isRunning}
              className={`w-full py-3 px-4 rounded-lg font-semibold flex items-center justify-center gap-2 transition-all ${
                isRunning 
                  ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                  : 'bg-slate-900 text-white hover:bg-slate-800 shadow-lg'
              }`}
             >
               {isRunning ? <Loader2 className="animate-spin h-4 w-4" /> : <Play className="h-4 w-4" />}
               {isRunning ? 'Agent Running...' : 'Run Global Scan'}
             </button>
          </div>
        </div>

        {/* Live Logs */}
        <div className="bg-slate-900 rounded-xl shadow-sm border border-slate-800 p-4 flex-1 flex flex-col min-h-0">
          <div className="flex items-center gap-2 text-slate-400 mb-3 pb-3 border-b border-slate-800">
            <Activity size={14} />
            <span className="text-xs font-mono font-bold uppercase">System Logs</span>
          </div>
          <div className="flex-1 overflow-y-auto font-mono text-xs space-y-2 pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
            {logs.length === 0 && <span className="text-slate-600 italic">Waiting to start...</span>}
            {logs.map((log, i) => (
              <div key={i} className="text-green-400 border-l-2 border-slate-700 pl-2 py-0.5">
                <span className="text-slate-500 mr-2">[{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}]</span>
                {log}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="lg:col-span-2 flex flex-col h-full overflow-hidden">
        <div className="flex items-center justify-between mb-4 flex-shrink-0">
          <div className="flex items-center gap-2">
            <h3 className="text-lg font-bold text-slate-900">Live Opportunities</h3>
            <span className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded flex items-center gap-1">
              <MapPin size={10}/> {fullLocation.split(',').slice(0,2).join(',')}
            </span>
          </div>
          {emailNotification && (
             <div className="flex items-center gap-2 bg-green-100 text-green-800 px-3 py-1 rounded-full text-xs font-bold animate-pulse">
               <Mail size={12} />
               Email Sent
             </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 space-y-4 scrollbar-hide">
          {jobs.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
              <Bot size={48} className="mb-4 opacity-50" />
              <p className="text-lg font-medium">Agent is sleeping</p>
              <p className="text-sm text-center max-w-md mt-2 px-4">
                Define your location hierarchy (Country to Town) and click "Run Global Scan" to start the automated executive search.
              </p>
            </div>
          ) : (
            jobs.map((job) => (
              <div key={job.id} className={`bg-white rounded-xl shadow-sm border p-5 transition-all ${
                job.status === 'applied' ? 'border-green-200 bg-green-50/30' : 
                job.status === 'rejected' ? 'border-slate-100 opacity-60' : 
                'border-slate-200'
              }`}>
                <div className="flex justify-between items-start mb-3">
                  <div className="flex-1">
                    <h4 className="font-bold text-slate-900 text-lg leading-tight">{job.title}</h4>
                    <div className="flex items-center gap-2 text-sm text-slate-600 mt-1">
                      <span className="font-medium">{job.company}</span>
                      <span>•</span>
                      <span className="flex items-center gap-0.5"><MapPin size={12}/> {job.location}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2 shrink-0 ml-4">
                     {job.status === 'analyzing' && <span className="bg-blue-100 text-blue-600 text-[10px] font-bold px-2 py-1 rounded flex items-center gap-1 uppercase tracking-wider"><Loader2 size={10} className="animate-spin"/> Analyzing</span>}
                     {job.status === 'matched' && <span className="bg-green-100 text-green-700 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider">Matched</span>}
                     {job.status === 'rejected' && <span className="bg-slate-100 text-slate-400 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider">Skipped</span>}
                     {job.status === 'applied' && <span className="bg-green-600 text-white text-[10px] font-bold px-2 py-1 rounded flex items-center gap-1 uppercase tracking-wider"><Send size={10}/> Applied</span>}
                  </div>
                </div>

                {job.analysis && (
                  <div className="mt-4 pt-4 border-t border-slate-100 grid grid-cols-4 gap-4">
                    <div className="col-span-1 border-r border-slate-100">
                      <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Fit</div>
                      <div className={`text-xl font-bold ${job.analysis.matchScore >= config.minScore ? 'text-green-600' : 'text-slate-400'}`}>
                        {job.analysis.matchScore}%
                      </div>
                    </div>
                    <div className="col-span-3">
                       <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Agent Verdict</div>
                       <p className="text-xs text-slate-700 line-clamp-2">{job.analysis.summary}</p>
                    </div>
                  </div>
                )}

                <div className="mt-4 flex justify-end">
                   <a href={job.url} target="_blank" rel="noreferrer" className="text-xs text-blue-600 hover:text-blue-800 font-semibold flex items-center gap-1 transition-colors">
                      Open Listing <ExternalLink size={12} />
                   </a>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { findRelevantJobs, analyzeJobFit } from '../services/geminiService';
import { JobSearchResult, UserProfile } from '../types';
import { 
  Bot, 
  Play, 
  Loader2, 
  Send, 
  Activity,
  Mail,
  ExternalLink,
  Ban,
  Settings2,
  Calendar,
  Globe,
  MapPin,
  ChevronRight,
  Info
} from 'lucide-react';

// Structured Global Location Data
// This provides a robust starting point. "Other..." allows for manual input to cover the whole world.
const GLOBAL_LOCATIONS: any = {
  "South Africa": {
    "Gauteng": {
      "Johannesburg": ["Sandton", "Randburg", "Midrand", "Soweto", "Bryanston", "Rosebank"],
      "Pretoria": ["Centurion", "Erasmuskloof", "Hatfield", "Brooklyn", "Silverton", "Garsfontein"],
    },
    "Western Cape": {
      "Cape Town": ["City Bowl", "Bellville", "Somerset West", "Stellenbosch", "Claremont"],
      "George": ["Wilderness", "Victoria Bay", "Knysna"]
    },
    "KwaZulu-Natal": {
      "Durban": ["Umhlanga", "Berea", "Westville", "Ballito"],
      "Pietermaritzburg": ["Hilton", "Howick"]
    }
  },
  "United States": {
    "California": {
      "Los Angeles": ["Santa Monica", "Beverly Hills", "Hollywood", "Venice"],
      "San Francisco": ["SoMa", "Mission District", "Marina", "Nob Hill"]
    },
    "New York": {
      "New York City": ["Manhattan", "Brooklyn", "Queens", "Bronx", "Staten Island"],
      "Buffalo": ["Amherst", "Cheektowaga"]
    },
    "Texas": {
      "Houston": ["The Woodlands", "Sugar Land", "Katy"],
      "Austin": ["Round Rock", "Cedar Park", "Pflugerville"]
    }
  },
  "United Kingdom": {
    "England": {
      "London": ["City of London", "Westminster", "Camden", "Greenwich", "Hackney"],
      "Manchester": ["Salford", "Trafford", "Stockport"]
    },
    "Scotland": {
      "Edinburgh": ["Leith", "Old Town", "New Town"],
      "Glasgow": ["West End", "City Centre", "South Side"]
    }
  }
};

interface AutoPilotProps {
  userProfile: UserProfile;
}

export const AutoPilot: React.FC<AutoPilotProps> = ({ userProfile }) => {
  const [isActive, setIsActive] = useState(true);
  const [isRunning, setIsRunning] = useState(false);
  const [jobs, setJobs] = useState<JobSearchResult[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [emailNotification, setEmailNotification] = useState<string | null>(null);

  // 4-Tier Hierarchical Location State
  const [loc, setLoc] = useState({
    country: "South Africa",
    state: "Gauteng",
    city: "Pretoria",
    town: "Erasmuskloof",
    customCountry: "",
    customState: "",
    customCity: "",
    customTown: ""
  });

  // Dynamic Options derived from data
  const countries = useMemo(() => [...Object.keys(GLOBAL_LOCATIONS), "Other..."], []);

  const states = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [loc.country]);

  const cities = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country]?.[loc.state];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [loc.country, loc.state]);

  const towns = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country]?.[loc.state]?.[loc.city];
    return data ? [...data, "Other..."] : ["Other..."];
  }, [loc.country, loc.state, loc.city]);

  // Configuration State
  const [config, setConfig] = useState({
    frequency: 'daily_9',
    minScore: 90,
    dateRange: '24h'
  });

  // Construct search string
  const currentTarget = useMemo(() => {
    const c = loc.country === "Other..." ? loc.customCountry : loc.country;
    const s = loc.state === "Other..." ? loc.customState : loc.state;
    const ci = loc.city === "Other..." ? loc.customCity : loc.city;
    const t = loc.town === "Other..." ? loc.customTown : loc.town;
    return [t, ci, s, c].filter(Boolean).join(", ");
  }, [loc]);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev]);

  const runAutomation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setJobs([]);
    setLogs([]);
    setEmailNotification(null);

    try {
      addLog("Initializing Executive Agent...");
      addLog(`Target Region: ${currentTarget}`);
      addLog(`Filtering for ${config.minScore}%+ matches...`);

      const foundJobs = await findRelevantJobs(userProfile, config.dateRange);
      setJobs(foundJobs);
      addLog(`Found ${foundJobs.length} potential listings. Starting deep analysis...`);

      for (const job of foundJobs) {
        setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'analyzing' } : j));
        addLog(`Analyzing fit: ${job.title} at ${job.company}`);

        const analysis = await analyzeJobFit(job.description, userProfile);
        const isMatch = analysis.matchScore >= config.minScore;

        setJobs(current => current.map(j => j.id === job.id ? { ...j, analysis, status: isMatch ? 'matched' : 'rejected' } : j));

        if (isMatch) {
          addLog(`✅ Match! Score ${analysis.matchScore}% - Executing application protocol.`);
          await new Promise(r => setTimeout(r, 1000));
          setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'applied' } : j));
          addLog(`🚀 Application successfully routed to ${job.company}`);
          setEmailNotification(`Match alert: ${job.company}`);
        } else {
          addLog(`⏭️ Skipped (${analysis.matchScore}%). Does not meet executive threshold.`);
        }
        await new Promise(r => setTimeout(r, 500));
      }
      addLog("Search cycle completed. Agent monitoring for new posts.");
    } catch (error) {
      addLog("⚠️ Automation interrupted. Check connectivity.");
      console.error(error);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-100px)]">
      {/* Configuration Sidebar */}
      <div className="lg:col-span-1 flex flex-col gap-4 min-h-0">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 overflow-y-auto scrollbar-hide flex-shrink-0">
          <div className="flex items-center gap-3 mb-5">
            <div className="bg-indigo-600 p-2 rounded-lg shadow-indigo-200 shadow-lg">
              <Bot className="text-white h-5 w-5" />
            </div>
            <div>
              <h2 className="text-md font-bold text-slate-900 leading-tight">Search Automation</h2>
              <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">MoJobs Agent v2.5</p>
            </div>
          </div>

          <div className="space-y-4">
             {/* Location Hierarchy - World Coverage */}
             <div className="bg-slate-50 rounded-xl border border-slate-100 p-4 space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-[11px] font-bold text-slate-900 uppercase flex items-center gap-1.5">
                    <Globe size={14} className="text-indigo-600" /> Target Region
                  </h4>
                  <Info size={12} className="text-slate-400 cursor-help" />
                </div>

                {/* Level 1: Country */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Country (Sovereign Nation)</label>
                  <select
                      value={loc.country}
                      onChange={(e) => setLoc({...loc, country: e.target.value, state: "Other...", city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {countries.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {loc.country === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter country name..."
                      value={loc.customCountry}
                      onChange={(e) => setLoc({...loc, customCountry: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 2: State / Province */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">State / Province / Region</label>
                  <select
                      value={loc.state}
                      onChange={(e) => setLoc({...loc, state: e.target.value, city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {states.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  {loc.state === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter state/province..."
                      value={loc.customState}
                      onChange={(e) => setLoc({...loc, customState: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 3: City */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">City (Large Urban Area)</label>
                  <select
                      value={loc.city}
                      onChange={(e) => setLoc({...loc, city: e.target.value, town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {loc.city === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter city name..."
                      value={loc.customCity}
                      onChange={(e) => setLoc({...loc, customCity: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 4: Town */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Town (Smaller Urban Area)</label>
                  <select
                      value={loc.town}
                      onChange={(e) => setLoc({...loc, town: e.target.value})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {towns.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                  {loc.town === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter town/suburb name..."
                      value={loc.customTown}
                      onChange={(e) => setLoc({...loc, customTown: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                <div className="flex items-center gap-2 pt-2 text-[10px] text-indigo-700 font-semibold bg-indigo-50/50 p-2 rounded-lg border border-indigo-100">
                  <MapPin size={14} />
                  <span className="truncate">Active Targeting: {currentTarget}</span>
                </div>
             </div>

             {/* Score Filter */}
             <div className="space-y-1 px-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Executive Match Score Filter</label>
                <select
                    value={config.minScore}
                    onChange={(e) => setConfig({...config, minScore: Number(e.target.value)})}
                    className="w-full text-xs p-2 rounded-lg border border-slate-200 bg-white text-slate-900"
                >
                    <option value={95}>95% (Highly Precise)</option>
                    <option value={90}>90% (Strict Executive)</option>
                    <option value={85}>85% (Balanced)</option>
                </select>
             </div>

             <button 
              onClick={runAutomation}
              disabled={isRunning}
