interface AutoPilotProps {
  userProfile: UserProfile;
}

export const AutoPilot: React.FC<AutoPilotProps> = ({ userProfile }) => {
  const [isActive, setIsActive] = useState(true);
  const [isRunning, setIsRunning] = useState(false);
  const [jobs, setJobs] = useState<JobSearchResult[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [emailNotification, setEmailNotification] = useState<string | null>(null);

  // 4-Tier Hierarchical Location State
  const [loc, setLoc] = useState({
    country: "South Africa",
    state: "Gauteng",
    city: "Pretoria",
    town: "Erasmuskloof",
    customCountry: "",
    customState: "",
    customCity: "",
    customTown: ""
  });

  // Dynamic Options derived from data
  const countries = useMemo(() => [...Object.keys(GLOBAL_LOCATIONS), "Other..."], []);

  const states = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [loc.country]);

  const cities = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country]?.[loc.state];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [loc.country, loc.state]);

  const towns = useMemo(() => {
    const data = GLOBAL_LOCATIONS[loc.country]?.[loc.state]?.[loc.city];
    return data ? [...data, "Other..."] : ["Other..."];
  }, [loc.country, loc.state, loc.city]);

  // Configuration State
  const [config, setConfig] = useState({
    frequency: 'daily_9',
    minScore: 90,
    dateRange: '24h'
  });

  // Construct search string
  const currentTarget = useMemo(() => {
    const c = loc.country === "Other..." ? loc.customCountry : loc.country;
    const s = loc.state === "Other..." ? loc.customState : loc.state;
    const ci = loc.city === "Other..." ? loc.customCity : loc.city;
    const t = loc.town === "Other..." ? loc.customTown : loc.town;
    return [t, ci, s, c].filter(Boolean).join(", ");
  }, [loc]);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev]);

  const runAutomation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setJobs([]);
    setLogs([]);
    setEmailNotification(null);

    try {
      addLog("Initializing Executive Agent...");
      addLog(`Target Region: ${currentTarget}`);
      addLog(`Filtering for ${config.minScore}%+ matches...`);

      const foundJobs = await findRelevantJobs(userProfile, config.dateRange);
      setJobs(foundJobs);
      addLog(`Found ${foundJobs.length} potential listings. Starting deep analysis...`);

      for (const job of foundJobs) {
        setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'analyzing' } : j));
        addLog(`Analyzing fit: ${job.title} at ${job.company}`);

        const analysis = await analyzeJobFit(job.description, userProfile);
        const isMatch = analysis.matchScore >= config.minScore;

        setJobs(current => current.map(j => j.id === job.id ? { ...j, analysis, status: isMatch ? 'matched' : 'rejected' } : j));

        if (isMatch) {
          addLog(`✅ Match! Score ${analysis.matchScore}% - Executing application protocol.`);
          await new Promise(r => setTimeout(r, 1000));
          setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'applied' } : j));
          addLog(`🚀 Application successfully routed to ${job.company}`);
          setEmailNotification(`Match alert: ${job.company}`);
        } else {
          addLog(`⏭️ Skipped (${analysis.matchScore}%). Does not meet executive threshold.`);
        }
        await new Promise(r => setTimeout(r, 500));
      }
      addLog("Search cycle completed. Agent monitoring for new posts.");
    } catch (error) {
      addLog("⚠️ Automation interrupted. Check connectivity.");
      console.error(error);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-100px)]">
      {/* Configuration Sidebar */}
      <div className="lg:col-span-1 flex flex-col gap-4 min-h-0">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 overflow-y-auto scrollbar-hide flex-shrink-0">
          <div className="flex items-center gap-3 mb-5">
            <div className="bg-indigo-600 p-2 rounded-lg shadow-indigo-200 shadow-lg">
              <Bot className="text-white h-5 w-5" />
            </div>
            <div>
              <h2 className="text-md font-bold text-slate-900 leading-tight">Search Automation</h2>
              <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">MoJobs Agent v2.5</p>
            </div>
          </div>

          <div className="space-y-4">
             {/* Location Hierarchy - World Coverage */}
             <div className="bg-slate-50 rounded-xl border border-slate-100 p-4 space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-[11px] font-bold text-slate-900 uppercase flex items-center gap-1.5">
                    <Globe size={14} className="text-indigo-600" /> Target Region
                  </h4>
                  <Info size={12} className="text-slate-400 cursor-help" />
                </div>

                {/* Level 1: Country */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Country (Sovereign Nation)</label>
                  <select
                      value={loc.country}
                      onChange={(e) => setLoc({...loc, country: e.target.value, state: "Other...", city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {countries.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {loc.country === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter country name..."
                      value={loc.customCountry}
                      onChange={(e) => setLoc({...loc, customCountry: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 2: State / Province */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">State / Province / Region</label>
                  <select
                      value={loc.state}
                      onChange={(e) => setLoc({...loc, state: e.target.value, city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {states.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  {loc.state === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter state/province..."
                      value={loc.customState}
                      onChange={(e) => setLoc({...loc, customState: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 3: City */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">City (Large Urban Area)</label>
                  <select
                      value={loc.city}
                      onChange={(e) => setLoc({...loc, city: e.target.value, town: "Other..."})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {loc.city === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter city name..."
                      value={loc.customCity}
                      onChange={(e) => setLoc({...loc, customCity: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                {/* Level 4: Town */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Town (Smaller Urban Area)</label>
                  <select
                      value={loc.town}
                      onChange={(e) => setLoc({...loc, town: e.target.value})}
                      className="w-full text-xs p-2.5 rounded-lg border border-slate-200 bg-white text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                      {towns.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                  {loc.town === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter town/suburb name..."
                      value={loc.customTown}
                      onChange={(e) => setLoc({...loc, customTown: e.target.value})}
                      className="w-full text-xs p-2.5 mt-1 rounded-lg border border-indigo-200 bg-white placeholder:text-slate-300"
                    />
                  )}
                </div>

                <div className="flex items-center gap-2 pt-2 text-[10px] text-indigo-700 font-semibold bg-indigo-50/50 p-2 rounded-lg border border-indigo-100">
                  <MapPin size={14} />
                  <span className="truncate">Active Targeting: {currentTarget}</span>
                </div>
             </div>

             {/* Score Filter */}
             <div className="space-y-1 px-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Executive Match Score Filter</label>
                <select
                    value={config.minScore}
                    onChange={(e) => setConfig({...config, minScore: Number(e.target.value)})}
                    className="w-full text-xs p-2 rounded-lg border border-slate-200 bg-white text-slate-900"
                >
                    <option value={95}>95% (Highly Precise)</option>
                    <option value={90}>90% (Strict Executive)</option>
                    <option value={85}>85% (Balanced)</option>
                </select>
             </div>

             <button 
              onClick={runAutomation}
              disabled={isRunning}
              className={`w-full py-3.5 px-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all active:scale-95 ${
                isRunning 
                  ? 'bg-slate-100 text-slate-400 cursor-not-allowed border border-slate-200' 
                  : 'bg-slate-900 text-white hover:bg-indigo-600 shadow-xl shadow-indigo-100'
              }`}
             >
               {isRunning ? <Loader2 className="animate-spin h-4 w-4" /> : <Play className="h-4 w-4" fill="currentColor" />}
               {isRunning ? 'Processing...' : 'Activate Agent'}
             </button>
          </div>
        </div>

        {/* Console Logs */}
        <div className="bg-slate-900 rounded-xl shadow-2xl border border-slate-800 p-4 flex-1 flex flex-col min-h-0 overflow-hidden">
          <div className="flex items-center justify-between text-slate-400 mb-3 pb-2 border-b border-slate-800">
            <div className="flex items-center gap-2">
              <Activity size={14} className="text-emerald-500" />
              <span className="text-[10px] font-mono font-bold uppercase tracking-tighter">Command Terminal</span>
            </div>
            <div className="flex gap-1">
              <div className="h-1.5 w-1.5 rounded-full bg-slate-700" />
              <div className="h-1.5 w-1.5 rounded-full bg-slate-700" />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto font-mono text-[10px] leading-relaxed space-y-1.5 scrollbar-thin scrollbar-thumb-slate-800">
            {logs.length === 0 && <span className="text-slate-600 italic animate-pulse">Waiting for commands...</span>}
            {logs.map((log, i) => (
              <div key={i} className="flex gap-2">
                <span className="text-slate-600 shrink-0">{new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', second:'2-digit'})}</span>
                <span className={log.startsWith('✅') ? 'text-emerald-400' : log.startsWith('🚀') ? 'text-indigo-400' : 'text-slate-300'}>
                  {log}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Results Display */}
      <div className="lg:col-span-2 flex flex-col h-full overflow-hidden">
        <div className="flex items-center justify-between mb-4 flex-shrink-0">
          <div className="flex flex-col">
            <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
              Detected Opportunities 
              <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full">{jobs.length} found</span>
            </h3>
            <p className="text-xs text-slate-500">Filtered for: {currentTarget}</p>
          </div>
          {emailNotification && (
             <div className="flex items-center gap-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-[10px] font-bold border border-emerald-100 animate-fade-in">
               <Mail size={12} />
               Notifications Sent
             </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 space-y-4 scrollbar-hide pb-8">
          {jobs.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-3xl bg-slate-50/50 p-12">
              <div className="bg-white p-6 rounded-full shadow-sm mb-6 border border-slate-100">
                <Bot size={48} className="text-slate-200" />
              </div>
              <p className="text-md font-bold text-slate-800">Agent Standby</p>
              <p className="text-xs text-center max-w-sm mt-2 text-slate-500">
                The agent will use Google Search and your executive profile to identify high-fit senior roles across all 4 location tiers.
              </p>
            </div>
          ) : (
            jobs.map((job) => (
              <div key={job.id} className={`bg-white rounded-2xl shadow-sm border p-6 transition-all group hover:shadow-md ${
                job.status === 'applied' ? 'border-emerald-200 bg-emerald-50/20' : 
                job.status === 'rejected' ? 'border-slate-100 opacity-60' : 
                'border-slate-200'
              }`}>
                <div className="flex justify-between items-start mb-4">
                  <div className="space-y-1">
                    <h4 className="font-bold text-slate-900 text-lg leading-tight group-hover:text-indigo-600 transition-colors">{job.title}</h4>
                    <div className="flex items-center gap-3 text-xs text-slate-500 font-medium">
                      <span className="text-slate-900 font-bold">{job.company}</span>
                      <span className="text-slate-300">|</span>
                      <span className="flex items-center gap-1"><MapPin size={12} className="text-indigo-400"/> {job.location}</span>
                    </div>
                  </div>
                  <div className="shrink-0 ml-4">
                     {job.status === 'analyzing' && <span className="bg-indigo-50 text-indigo-600 text-[9px] font-black px-2.5 py-1.5 rounded-lg flex items-center gap-1.5 uppercase tracking-widest border border-indigo-100"><Loader2 size={10} className="animate-spin"/> Scanning</span>}
                     {job.status === 'matched' && <span className="bg-emerald-50 text-emerald-700 text-[9px] font-black px-2.5 py-1.5 rounded-lg uppercase tracking-widest border border-emerald-100">Verified Fit</span>}
                     {job.status === 'rejected' && <span className="bg-slate-50 text-slate-400 text-[9px] font-black px-2.5 py-1.5 rounded-lg uppercase tracking-widest border border-slate-100">Below Threshold</span>}
                     {job.status === 'applied' && <span className="bg-slate-900 text-white text-[9px] font-black px-2.5 py-1.5 rounded-lg flex items-center gap-1.5 uppercase tracking-widest shadow-lg shadow-indigo-100"><CheckCircle2 size={10} className="text-emerald-400"/> Dispatched</span>}
                  </div>
                </div>

                {job.analysis && (
                  <div className="mb-4 bg-slate-50/80 rounded-xl p-4 border border-slate-100">
                    <div className="flex items-center gap-4">
                      <div className="shrink-0 text-center px-4 border-r border-slate-200">
                        <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Exec Fit</div>
                        <div className={`text-2xl font-black ${job.analysis.matchScore >= config.minScore ? 'text-indigo-600' : 'text-slate-400'}`}>
                          {job.analysis.matchScore}%
                        </div>
                      </div>
                      <div className="flex-1">
                         <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter mb-1">Agent Assessment</div>
                         <p className="text-xs text-slate-600 leading-relaxed italic">"{job.analysis.summary}"</p>
                      </div>
                    </div>
                  </div>
                )}

                <div className="flex justify-between items-center pt-2">
                   <div className="flex gap-2">
                      {job.analysis?.matchingKeywords.slice(0, 3).map((tag, idx) => (
                        <span key={idx} className="text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded">#{tag.toLowerCase().replace(/\s+/g, '')}</span>
                      ))}
                   </div>
                   <a href={job.url} target="_blank" rel="noreferrer" className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg hover:bg-indigo-600 hover:text-white transition-all flex items-center gap-1.5">
                      Verify Position <ExternalLink size={10} />
                   </a>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
