import React, { useState, useEffect, useMemo } from 'react';
import { findRelevantJobs, analyzeJobFit } from '../services/geminiService';
import { JobSearchResult, UserProfile } from '../types';
import { GLOBAL_GEOGRAPHY_DB } from '../geography';
import { 
  Bot, 
  Play, 
  Loader2, 
  Send, 
  Activity,
  Mail,
  ExternalLink,
  Settings2,
  Globe,
  MapPin,
  Info,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';

interface AutoPilotProps {
  userProfile: UserProfile;
}

export const AutoPilot: React.FC<AutoPilotProps> = ({ userProfile }) => {
  const [isActive, setIsActive] = useState(true);
  const [isRunning, setIsRunning] = useState(false);
  const [jobs, setJobs] = useState<JobSearchResult[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [emailNotification, setEmailNotification] = useState<string | null>(null);

  // 4-Tier Hierarchical State
  const [geo, setGeo] = useState({
    country: "South Africa",
    division: "Gauteng",
    city: "Pretoria",
    town: "Erasmuskloof",
    customCountry: "",
    customDivision: "",
    customCity: "",
    customTown: ""
  });

  // Dynamic Data Extraction
  const countryData = GLOBAL_GEOGRAPHY_DB[geo.country];
  const divisionLabel = countryData?.divisionType === 'None' ? 'Area' : (countryData?.divisionType || "State/Province");

  // Options Memoization
  const countries = useMemo(() => [...Object.keys(GLOBAL_GEOGRAPHY_DB), "Other..."], []);

  const divisions = useMemo(() => {
    const data = GLOBAL_GEOGRAPHY_DB[geo.country]?.divisions;
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [geo.country]);

  const cities = useMemo(() => {
    const data = GLOBAL_GEOGRAPHY_DB[geo.country]?.divisions?.[geo.division];
    return data ? [...Object.keys(data), "Other..."] : ["Other..."];
  }, [geo.country, geo.division]);

  const towns = useMemo(() => {
    const data = GLOBAL_GEOGRAPHY_DB[geo.country]?.divisions?.[geo.division]?.[geo.city];
    return data ? [...data, "Other..."] : ["Other..."];
  }, [geo.country, geo.division, geo.city]);

  // Configuration State
  const [config, setConfig] = useState({
    frequency: 'daily_9',
    minScore: 90,
    dateRange: '24h'
  });

  // Target String Construction
  const currentTarget = useMemo(() => {
    const c = geo.country === "Other..." ? geo.customCountry : geo.country;
    const d = geo.division === "Other..." ? geo.customDivision : geo.division;
    const ci = geo.city === "Other..." ? geo.customCity : geo.city;
    const t = geo.town === "Other..." ? geo.customTown : geo.town;

    // For unitary states, we might skip the division label in the UI display but include it in search
    return [t, ci, d, c].filter(Boolean).join(", ");
  }, [geo]);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev]);

  const runAutomation = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setJobs([]);
    setLogs([]);
    setEmailNotification(null);

    try {
      addLog("Initializing MoJobs Global Agent...");
      addLog(`Setting search perimeter: ${currentTarget}`);

      const tempProfile = { ...userProfile, location: currentTarget };
      const foundJobs = await findRelevantJobs(tempProfile, config.dateRange);
      setJobs(foundJobs);

      addLog(`Detected ${foundJobs.length} matches. Commencing Executive compatibility analysis...`);

      for (const job of foundJobs) {
        setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'analyzing' } : j));
        addLog(`Analyzing: ${job.title} at ${job.company}`);

        const analysis = await analyzeJobFit(job.description, userProfile);
        const isMatch = analysis.matchScore >= config.minScore;

        setJobs(current => current.map(j => j.id === job.id ? { ...j, analysis, status: isMatch ? 'matched' : 'rejected' } : j));

        if (isMatch) {
          addLog(`✅ VERIFIED: ${analysis.matchScore}% Match. Initiating outreach...`);
          await new Promise(r => setTimeout(r, 1000));
          setJobs(current => current.map(j => j.id === job.id ? { ...j, status: 'applied' } : j));
          addLog(`🚀 Application successfully dispatched to ${job.company}`);
          setEmailNotification(`Match alert: ${job.company}`);
        } else {
          addLog(`⏭️ Filtered: ${analysis.matchScore}% score. Insufficient role alignment.`);
        }
        await new Promise(r => setTimeout(r, 500));
      }
      addLog("Agent scan cycle complete. System set to idle/monitoring.");
    } catch (error) {
      addLog("⚠️ Search Engine Error: Check API reachability.");
      console.error(error);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-100px)]">
      {/* Control Panel */}
      <div className="lg:col-span-1 flex flex-col gap-4 min-h-0">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 overflow-y-auto scrollbar-hide flex-shrink-0">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-slate-900 p-2.5 rounded-xl shadow-lg shadow-slate-200">
              <Bot className="text-white h-5 w-5" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-900 tracking-tight">Agent Control</h2>
              <p className="text-[10px] text-slate-500 uppercase tracking-widest font-black">Global Strategy Active</p>
            </div>
          </div>

          <div className="space-y-5">
             {/* 4-Tier Geographic Hierarchy */}
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-5 space-y-4">
                <div className="flex items-center justify-between border-b border-slate-200 pb-3 mb-1">
                  <h4 className="text-[11px] font-black text-slate-700 uppercase flex items-center gap-2 tracking-tight">
                    <Globe size={14} className="text-blue-600" /> Geography Database
                  </h4>
                  {countryData?.explanation && (
                    <div className="group relative">
                      <AlertCircle size={14} className="text-blue-400 cursor-help" />
                      <div className="absolute right-0 bottom-full mb-2 w-48 bg-slate-800 text-white text-[10px] p-2 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                        {countryData.explanation}
                      </div>
                    </div>
                  )}
                </div>

                {/* Level 1: Country */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">1. Country</label>
                  <select
                      value={geo.country}
                      onChange={(e) => setGeo({...geo, country: e.target.value, division: "Other...", city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-3 rounded-xl border border-slate-200 bg-white text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
                  >
                      {countries.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {geo.country === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter country name..."
                      value={geo.customCountry}
                      onChange={(e) => setGeo({...geo, customCountry: e.target.value})}
                      className="w-full text-xs p-3 mt-1.5 rounded-xl border border-blue-200 bg-white"
                    />
                  )}
                </div>

                {/* Level 2: Division (State/Province/Emirate) */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">2. {divisionLabel}</label>
                  <select
                      value={geo.division}
                      onChange={(e) => setGeo({...geo, division: e.target.value, city: "Other...", town: "Other..."})}
                      className="w-full text-xs p-3 rounded-xl border border-slate-200 bg-white text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
                  >
                      {divisions.map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                  {geo.division === "Other..." && (
                    <input 
                      type="text"
                      placeholder={`Enter ${divisionLabel.toLowerCase()}...`}
                      value={geo.customDivision}
                      onChange={(e) => setGeo({...geo, customDivision: e.target.value})}
                      className="w-full text-xs p-3 mt-1.5 rounded-xl border border-blue-200 bg-white"
                    />
                  )}
                </div>

                {/* Level 3: City */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">3. City</label>
                  <select
                      value={geo.city}
                      onChange={(e) => setGeo({...geo, city: e.target.value, town: "Other..."})}
                      className="w-full text-xs p-3 rounded-xl border border-slate-200 bg-white text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
                  >
                      {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  {geo.city === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter city name..."
                      value={geo.customCity}
                      onChange={(e) => setGeo({...geo, customCity: e.target.value})}
                      className="w-full text-xs p-3 mt-1.5 rounded-xl border border-blue-200 bg-white"
                    />
                  )}
                </div>

                {/* Level 4: Town */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">4. Town / Suburb</label>
                  <select
                      value={geo.town}
                      onChange={(e) => setGeo({...geo, town: e.target.value})}
                      className="w-full text-xs p-3 rounded-xl border border-slate-200 bg-white text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
                  >
                      {towns.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                  {geo.town === "Other..." && (
                    <input 
                      type="text"
                      placeholder="Enter town/suburb..."
                      value={geo.customTown}
                      onChange={(e) => setGeo({...geo, customTown: e.target.value})}
                      className="w-full text-xs p-3 mt-1.5 rounded-xl border border-blue-200 bg-white"
                    />
                  )}
                </div>

                <div className="flex items-center gap-2.5 pt-3 text-[11px] text-blue-700 font-bold bg-white p-3 rounded-xl border border-blue-100 shadow-sm">
                  <MapPin size={16} className="text-blue-600 shrink-0" />
                  <span className="truncate">Target: {currentTarget}</span>
                </div>
             </div>

             <div className="space-y-1.5 px-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Match Quality Filter</label>
                <select
                    value={config.minScore}
                    onChange={(e) => setConfig({...config, minScore: Number(e.target.value)})}
                    className="w-full text-xs p-3 rounded-xl border border-slate-200 bg-white text-slate-900 font-semibold shadow-sm"
                >
                    <option value={95}>95% (Highly Stringent)</option>
                    <option value={90}>90% (Standard Executive)</option>
                    <option value={85}>85% (Broad Scan)</option>
                </select>
             </div>

             <button 
              onClick={runAutomation}
              disabled={isRunning}
              className={`w-full py-4 px-6 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 transition-all active:scale-95 shadow-lg ${
                isRunning 
                  ? 'bg-slate-100 text-slate-400 cursor-not-allowed border border-slate-200' 
                  : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-100'
              }`}
             >
               {isRunning ? <Loader2 className="animate-spin h-5 w-5" /> : <Play className="h-5 w-5" fill="currentColor" />}
               {isRunning ? 'Processing...' : 'Deploy Agent'}
             </button>
          </div>
        </div>

        {/* Status Terminal */}
        <div className="bg-slate-900 rounded-2xl shadow-xl border border-slate-800 p-5 flex-1 flex flex-col min-h-0 overflow-hidden">
          <div className="flex items-center justify-between text-slate-500 mb-4 pb-3 border-b border-slate-800">
            <div className="flex items-center gap-2.5">
              <Activity size={16} className="text-blue-500" />
              <span className="text-[10px] font-mono font-black uppercase tracking-widest">Agent System Logs</span>
            </div>
            <div className="flex gap-1.5">
              <div className="h-2 w-2 rounded-full bg-slate-800" />
              <div className="h-2 w-2 rounded-full bg-slate-800" />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto font-mono text-[10px] leading-relaxed space-y-2 scrollbar-thin scrollbar-thumb-slate-800 pr-2">
            {logs.length === 0 && <span className="text-slate-700 italic">Agent idling. Select target and deploy...</span>}
            {logs.map((log, i) => (
              <div key={i} className="flex gap-3">
                <span className="text-slate-600 shrink-0">[{new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', second:'2-digit'})}]</span>
                <span className={log.startsWith('✅') ? 'text-emerald-400' : log.startsWith('🚀') ? 'text-blue-400' : 'text-slate-300'}>
                  {log}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Results Display */}
      <div className="lg:col-span-2 flex flex-col h-full overflow-hidden">
        <div className="flex items-center justify-between mb-5 flex-shrink-0 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex flex-col">
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2 tracking-tight">
              Opportunities Found
              {jobs.length > 0 && <span className="text-[10px] bg-blue-600 text-white px-2.5 py-1 rounded-full font-bold">{jobs.length} Active</span>}
            </h3>
            <p className="text-xs text-slate-500 font-medium">Scanned Region: {currentTarget}</p>
          </div>
          {emailNotification && (
             <div className="flex items-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-2 rounded-full text-[10px] font-black border border-emerald-100 animate-pulse uppercase tracking-widest">
               <Mail size={14} />
               Alert Sent
             </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto pr-2 space-y-5 scrollbar-hide pb-12">
          {jobs.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-slate-50/50 p-12">
              <div className="bg-white p-8 rounded-full shadow-lg border border-slate-100 mb-8">
                <Globe size={64} className="text-slate-200" />
              </div>
              <p className="text-xl font-black text-slate-800 tracking-tight">Agent Standby</p>
              <p className="text-sm text-center max-w-sm mt-3 text-slate-500 font-medium leading-relaxed">
                The agent is ready to traverse global job markets. Configure your 4-tier location hierarchy and click "Deploy Agent" to begin the executive search.
              </p>
            </div>
          ) : (
            jobs.map((job) => (
              <div key={job.id} className={`bg-white rounded-3xl shadow-sm border p-7 transition-all group hover:shadow-xl ${
                job.status === 'applied' ? 'border-emerald-200 bg-emerald-50/30' : 
                job.status === 'rejected' ? 'border-slate-100 opacity-60' : 
                'border-slate-200'
              }`}>
                <div className="flex justify-between items-start mb-5">
                  <div className="space-y-1.5 flex-1">
                    <h4 className="font-black text-slate-900 text-xl leading-none tracking-tight group-hover:text-blue-600 transition-colors">{job.title}</h4>
                    <div className="flex flex-wrap items-center gap-3 text-[11px] text-slate-500 font-bold uppercase tracking-wider">
                      <span className="text-slate-900">{job.company}</span>
                      <span className="text-slate-300">•</span>
                      <span className="flex items-center gap-1.5"><MapPin size={12} className="text-blue-500"/> {job.location}</span>
                    </div>
                  </div>
                  <div className="shrink-0 ml-4">
                     {job.status === 'analyzing' && <span className="bg-blue-50 text-blue-600 text-[9px] font-black px-3 py-2 rounded-xl flex items-center gap-2 uppercase tracking-widest border border-blue-100"><Loader2 size={10} className="animate-spin"/> Scanning</span>}
                     {job.status === 'matched' && <span className="bg-emerald-50 text-emerald-700 text-[9px] font-black px-3 py-2 rounded-xl uppercase tracking-widest border border-emerald-100">Verified Fit</span>}
                     {job.status === 'rejected' && <span className="bg-slate-50 text-slate-400 text-[9px] font-black px-3 py-2 rounded-xl uppercase tracking-widest border border-slate-100">Low Affinity</span>}
                     {job.status === 'applied' && <span className="bg-slate-900 text-white text-[9px] font-black px-3 py-2 rounded-xl flex items-center gap-2 uppercase tracking-widest"><CheckCircle2 size={12} className="text-emerald-400"/> Applied</span>}
                  </div>
                </div>

                {job.analysis && (
                  <div className="mb-5 bg-slate-50 rounded-2xl p-5 border border-slate-100">
                    <div className="flex items-center gap-6">
                      <div className="shrink-0 text-center px-5 border-r border-slate-200">
                        <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Match</div>
                        <div className={`text-3xl font-black ${job.analysis.matchScore >= config.minScore ? 'text-blue-600' : 'text-slate-400'}`}>
                          {job.analysis.matchScore}%
                        </div>
                      </div>
                      <div className="flex-1">
                         <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5">Assessment</div>
                         <p className="text-xs text-slate-600 leading-relaxed font-medium italic">"{job.analysis.summary}"</p>
                      </div>
                    </div>
                  </div>
                )}

                <div className="flex justify-between items-center pt-2">
                   <div className="flex gap-2.5">
                      {job.analysis?.matchingKeywords.slice(0, 3).map((tag, idx) => (
                        <span key={idx} className="text-[10px] font-bold text-slate-500 bg-slate-100 px-3 py-1 rounded-lg border border-slate-200">#{tag.toLowerCase().replace(/\s+/g, '')}</span>
                      ))}
                   </div>
                   <a href={job.url} target="_blank" rel="noreferrer" className="text-[11px] font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl hover:bg-blue-600 hover:text-white transition-all flex items-center gap-2 uppercase tracking-widest border border-blue-100">
                      View Original <ExternalLink size={12} />
                   </a>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

